220	\begin{theorem}[Quantum soundness of the simultaneous classical low individual degree test]\label{lem:ld-soundness}
221		\lean{MIPStarRE.QPBT.deltaLd, MIPStarRE.QPBT.exists_ld_soundness}
222		\leanok
223		\uses{def:ld-game, def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:projective-strategy-general, def:tensor-product-value, def:consistency, def:bracket}
224		There exists a function
225		\[
226			\delta_{\mathrm{ld}}(\eps, q, m, d, k) = a\,(dmk)^a \bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)
227		\]
228		for universal constants $a \ge 1$ and $0 < b \le 1$ such that the following holds. For all $\eps > 0$ and every parameter tuple $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game} (so $m, d, k \ge 1$, $q$ is an admissible field size, and $m$ divides $q$), and for all projective strategies $(\psi, A, B)$ that succeed with probability at least $1-\eps$ in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$, there exist measurements
229		\[
230			G^w \in \mathrm{PolyMeas}(m,q,d,k)
231		\]
232		on $\hilb_w$ for $w \in \{\mathrm A,\mathrm B\}$, where by slight abuse of notation $m$, $q$, $d$ denote the constant tuples $(m,\ldots,m)$, $(q,\ldots,q)$, $(d,\ldots,d)$ of length $k$, such that
233		\begin{align*}
234			A^{\mathsf{Point},\, u}_{a_1,\ldots,a_k} \ot I_{\mathrm B}
235			&\simeq_{\delta_{\mathrm{ld}}}
236			I_{\mathrm A} \ot G^{\mathrm B}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]}\;,\\
237			G^{\mathrm A}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]} \ot I_{\mathrm B}
238			&\simeq_{\delta_{\mathrm{ld}}}
239			I_{\mathrm A} \ot B^{\mathsf{Point},\, u}_{a_1,\ldots,a_k}\;,\\
240			G^{\mathrm A}_{g_1,\ldots,g_k} \ot I_{\mathrm B}
241			&\simeq_{\delta_{\mathrm{ld}}}
242			I_{\mathrm A} \ot G^{\mathrm B}_{g_1,\ldots,g_k}\;,
243		\end{align*}
244		where $\delta_{\mathrm{ld}} = \delta_{\mathrm{ld}}(\eps,q,m,d,k)$, all three relations are the state-dependent consistency $\simeq$ of Definition~\ref{def:consistency} with respect to the state $\ket{\psi}$, and the bracket notation for post-processed outcomes is that of Definition~\ref{def:bracket}. The first two relations hold on average over the uniform distribution on $u \in \F_q^m$; no question distribution is associated with the third.
245	\end{theorem}
246	\begin{proof}
247		\uses{def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:povm-distance}
248		Let $\Sigma = \F_q$ and let $\code \subseteq \Sigma^q$ be the Reed--Solomon code of degree $d$: the set of all $(p(x_1),\ldots,p(x_q))$ where $p\colon \F_q \to \F_q$ is a univariate polynomial of degree at most $d$ and $x_1,\ldots,x_q$ enumerate $\F_q$. We may assume $d < q$. In the opposite regime the statement is immediate: for $d \ge q$ the prefactor gives $\delta_{\mathrm{ld}} \ge a\,(dmk)^a\, q^{-b} \ge q^{a-b} \ge 1$, using $m, k \ge 1$, while the quantity bounded in Definition~\ref{def:consistency} never exceeds $4$ for families of POVM elements: $\sum_a \lVert (A_a \ot I - I \ot B_a)\ket{\psi}\rVert^2 \le 2\sum_a \bigl(\bra{\psi} A_a^2 \ot I \ket{\psi} + \bra{\psi} I \ot B_a^2 \ket{\psi}\bigr) \le 4$, using $0 \le M_a^2 \le M_a$ and $\sum_a M_a = \Id$ for POVM elements, so the three relations hold for an arbitrary choice of $G^w \in \mathrm{PolyMeas}(m,q,d,k)$. For $d < q$, evaluation is injective on polynomials of degree at most $d$ and a nonzero polynomial of degree at most $d$ vanishes at no more than $d$ of the $q$ points, so $\code$ is a linear $[q,\, d+1,\, q-d]_\Sigma$ code.
249		% The paper prints the parameters as [q, d+1, n-d+1] with an undefined n. With the
250		% intended value n = q the printed distance q-d+1 exceeds the true minimum distance
251		% q-d of the degree-d evaluation code, and the dimension claim d+1 requires d < q.
252		% Both points are corrected above; the regime d >= q, which the parameter tuple of
253		% Definition def:ld-game permits, is handled by the triviality argument. The
254		% boundary values d = 0 and k = 0 are excluded by the parameter domain of
255		% Definition def:ld-game, following the source's convention that \N denotes
256		% the positive integers.
257		% The source asserts a flat identity between its game and the two-prover
258		% tensor-code test and applies Theorem 4.7 of ji2021quantum with the
259		% parameter choice m^3 d
260		% (references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:446-454),
261		% without checking that theorem's hypothesis k >= 12mt on the parameter.
262		% Inspection of the cited test (arXiv:2111.08131, Figures 1 and 2,
263		% Definitions 4.5-4.6, Theorem 4.7) shows the asserted identity is not one:
264		% the question formats, the branch weights, and the zero-direction
265		% convention all differ, and the parameter bound fails at small m. Per the
266		% import policy, this proof states the source's route and enumerates
267		% the facts required by the identification, which remain to be proved, as open obligations; the
268		% detailed comparison and the case arithmetic are in the import-obligations
269		% section of docs/paper-gaps/qpbt_ld-dimension-divisibility.tex.
270		In this regime the statement is imported, and the source's route is as follows: identify the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ with $k = 1$ with the two-prover tensor-code test for the code $\code^{\ot m}$ of~\cite{Ji2021Quantum} (Figures~1 and~2 there, the roles of the two players being assigned uniformly at random); apply Theorem~4.7 of~\cite{Ji2021Quantum}, instantiated with its auxiliary integer parameter --- denoted $k$ there and unrelated to the simultaneity parameter $k$ of $\mathsf{ldparams}$ --- chosen as $m^3 d$, so that its error function $\mathrm{poly}(m, d+1, m^3d) \cdot \mathrm{poly}(\eps, q^{-1}, e^{-md})$ takes the displayed form of $\delta_{\mathrm{ld}}$; and extend from $k = 1$ to general $k$ by a standard reduction, following exactly the derivation of Theorem~4.43 from Theorem~4.40 in~\cite{Natarajan2018NEEXP}. The import carries two verification obligations, which remain open; they are enumerated here as obligations and detailed, together with candidate repairs, in the import-obligations section of~\cite{gap:qpbt_ld-dimension-divisibility}.
271		\begin{enumerate}
272			\item (\emph{Game correspondence.}) The source asserts that the two games are identical; they are not. In the cited test, the subcube commutation and pair-synchronicity branches send an ordered pair of points of a \emph{hidden} subcube and receive a pair of field values --- a question type that $\mathfrak{G}^{\mathrm{ld}}$ does not have --- its line questions carry no analogue of the seed $s$, its nontrivial cross-tests have mass $1/3$ where the present ones have $2/9$, and it fixes no acceptance convention on the zero-direction event of Remark~\ref{rem:ld-win-zero-direction}, whose probability is at most $\frac1m \sum_{j=1}^m q^{-j} \le \frac{1}{m(q-1)} \le \frac{2}{mq}$ over uniform $(s,v)$. What must be proved is a reduction converting any projective strategy for $\mathfrak{G}^{\mathrm{ld}}$ with success probability $1-\eps$ into a two-prover strategy for the tensor-code test with rejection probability at most $\tfrac32\,\eps + O(1/(mq))$ --- the factor $\tfrac32$ being the target bookkeeping constant from the branch weights, and the $O(1/(mq))$ the zero-direction term. A deficit of this shape is then absorbed into $\delta_{\mathrm{ld}}$ by enlarging the universal constant $a$, since $(x+y)^b \le x^b + y^b$ for $0 < b \le 1$ and $(2/(mq))^b \le 2\,q^{-b}$ for $m \ge 1$, using $dmk \ge 1$.
273			\item (\emph{Parameter bound.}) Theorem~4.7 requires its auxiliary parameter to be at least $12mt$, where $t$ is the interpolation parameter of the base code, equal to $d+1$ for the degree-$d$ Reed--Solomon code $\code$ (blocklength $q$, distance $q-d$). The choice $m^3 d$ satisfies $m^3 d \ge 12m(d+1)$ if and only if $m^2 d \ge 12(d+1)$, which holds for all $d \ge 1$ when $m \ge 5$ and, at $m = 4$, exactly when $d \ge 3$, but fails for every $d$ when $m \le 3$. Over the parameter domain of Definition~\ref{def:ld-game}, where $m$ divides the admissible field size $q$ and is therefore a power of $2$, the bound thus fails exactly at $m \in \{1,2\}$ for every $d$ and at $m = 4$ for $d \in \{1,2\}$; the case check and the candidate repair --- instantiating the parameter as $\max(m^3 d,\, 12m(d+1))$ and re-absorbing the error terms --- are in the note.
274		\end{enumerate}
275		Quantum soundness of the low individual degree test itself is the result of~\cite{Ji2020LowIndividualDegree}; Remark~\ref{rem:ld-soundness-provider} relates the present statement to Theorem~\ref{thm:main-formal}, which proves that result.
276	\end{proof}
